import React from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import styles from './HomePage.module.css';

const HomePage = () => (
  <motion.div className={styles.hero} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.8 }}>
    <h1>Элитные автомобили</h1>
    <p>Откройте мир роскоши и скорости</p>
    <Link to="/catalog" className={styles.cta}>Смотреть каталог</Link>
  </motion.div>
);

export default HomePage;
